// Eclipse toggle: The moon slides over the sun: twilight, totality, then the corona flares.
// One file, no dependencies. From https://zerowing.in/toggles/
//
// Use it:
//   <script type="module" src="eclipse.js"></script>
//
//   <tg-eclipse style="display:block; width:360px; height:220px"></tg-eclipse>
//
//   <script type="module">
//     const t = document.querySelector("tg-eclipse");
//     t.addEventListener("change", (e) => console.log("on?", e.detail.checked));
//     // t.checked = true;  t.toggle();
//   </script>
//
// API: the `checked` attribute / .checked property, .toggle(), a "change" event ({detail: {checked}}).
// The switch scales to fit its box (designed at 360x220); fill="0.9" sets how much of the box it fills (default 0.82).
// The element paints its own scene background, so give it a rounded container if you want one.

// ---- shared base ----
// Shared base for every toggle in the library.
//
// Contract (every components/<id>.js follows it):
//   - `export default class extends ToggleBase` and `customElements.define('tg-<id>', …)` at the bottom.
//   - Override `template()` → HTML string for the shadow root (include its own <style>).
//     Everything is drawn inside a fixed design stage of W×H px (static W/H, default 360×220);
//     the base scales that stage to fit the host. The host itself is the full scene (paint
//     :host's background yourself if the style swaps day/night etc.).
//   - Override `render(on, instant)` → apply the on/off state. `instant` is true on first paint.
//   - Optional `tick(t, dt)` → called every animation frame while connected (t in ms, from
//     performance.now(), so a virtual clock can drive it). Return nothing.
//   - Any element with [data-hit] is the clickable switch; clicking it calls this.toggle().
//   - Time sources: only performance.now() / rAF / CSS transitions & animations. No setTimeout
//     chains for visible motion (capture seeks a virtual clock).
//
// Public API on every element: .checked (bool, reflects the `checked` attribute), .toggle(),
// 'change' event with detail {checked}. this.scale = current stage scale, this.dpr = devicePixelRatio.

class ToggleBase extends HTMLElement {
  static W = 360;
  static H = 220;
  static observedAttributes = ['checked'];

  constructor() {
    super();
    this.root = this.attachShadow({ mode: 'open' });
    this.scale = 1;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this._raf = 0;
    this._last = 0;
  }

  template() { return ''; }
  render(_on, _instant) {}
  tick(_t, _dt) {}
  onResize() {}

  connectedCallback() {
    if (!this._built) {
      const { W, H } = this.constructor;
      this.root.innerHTML = `
        <style>
          :host { display: block; position: relative; overflow: hidden; contain: content; -webkit-tap-highlight-color: transparent; }
          .tg-stage { position: absolute; left: 50%; top: 50%; width: ${W}px; height: ${H}px;
            transform: translate(-50%, -50%) scale(var(--s, 1)); transform-origin: 50% 50%; }
          [data-hit] { cursor: pointer; }
        </style>
        <div class="tg-stage">${this.template()}</div>`;
      this.stage = this.root.querySelector('.tg-stage');
      this.root.addEventListener('click', (e) => {
        if (e.composedPath().some((n) => n instanceof Element && n.hasAttribute('data-hit'))) this.toggle();
      });
      this._built = true;
      this.setup?.();
      this.render(this.checked, true);
    }
    this._ro = new ResizeObserver(() => this._fit());
    this._ro.observe(this);
    this._fit();
    const loop = (t) => {
      const dt = this._last ? Math.min(t - this._last, 64) : 16;
      this._last = t;
      this.tick(t, dt);
      this._raf = requestAnimationFrame(loop);
    };
    this._raf = requestAnimationFrame(loop);
  }

  disconnectedCallback() {
    cancelAnimationFrame(this._raf);
    this._ro?.disconnect();
    this._last = 0;
  }

  _fit() {
    const { W, H } = this.constructor;
    const r = this.getBoundingClientRect();
    if (!r.width || !r.height) return;
    // Toggle fills ~78% of the shorter fit so every tile has breathing room.
    this.scale = Math.min(r.width / W, r.height / H) * (parseFloat(this.getAttribute('fill')) || 0.82);
    this.style.setProperty('--s', this.scale);
    this.onResize();
  }

  get checked() { return this.hasAttribute('checked'); }
  set checked(v) { this.toggleAttribute('checked', !!v); }

  attributeChangedCallback(name, oldV, newV) {
    if (name === 'checked' && this._built && (oldV === null) !== (newV === null)) {
      this.render(this.checked, false);
      this.dispatchEvent(new CustomEvent('change', { detail: { checked: this.checked }, bubbles: true }));
    }
  }

  toggle() { this.checked = !this.checked; }

  $(sel) { return this.root.querySelector(sel); }
  $$(sel) { return [...this.root.querySelectorAll(sel)]; }

  // Size a <canvas> to cover `w×h` design px at full device resolution.
  sizeCanvas(cv, w, h) {
    const k = this.scale * this.dpr;
    cv.width = Math.max(1, Math.round(w * k));
    cv.height = Math.max(1, Math.round(h * k));
    cv.style.width = w + 'px';
    cv.style.height = h + 'px';
    const ctx = cv.getContext('2d');
    ctx.setTransform(k, 0, 0, k, 0, 0);
    return ctx;
  }
}

// Easing helpers shared by components.
const ease = {
  outCubic: (x) => 1 - Math.pow(1 - x, 3),
  inOutCubic: (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2),
  outBack: (x, s = 1.70158) => 1 + (s + 1) * Math.pow(x - 1, 3) + s * Math.pow(x - 1, 2),
  // Critically-damped-ish spring step: returns new [pos, vel].
  spring: (pos, vel, target, dt, k = 170, d = 18) => {
    const s = dt / 1000;
    const a = -k * (pos - target) - d * vel;
    vel += a * s;
    pos += vel * s;
    return [pos, vel];
  },
};

const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;

// ---- Eclipse ----
// 07 Eclipse — the moon glides along a glowing orbit ring and covers the sun.
// Everything (sky darkening, corona, diamond ring, Baily's beads) is driven by the
// geometric overlap of the two discs, so the transition is continuous both ways.

// Snow Globe standard: bezel 330×160 at (15,30), 15px frame, window 300×130 (r 65), discs Ø112 with a 9px gap.
const CX = 180, CY = 110;          // stage centre
const TW = 300, TH = 130;           // window pill
const WX = CX - TW / 2, WY = CY - TH / 2;
const BZ = 15;                      // bezel frame thickness
const RM = 56, RS = 54.6;           // moon / sun radius (moon a bit larger → totality)
const K = RS / 30;                  // detail scale vs. the original 30px sun
const SX0 = WX + TH / 2;            // sun rest x (left end of the window) — the sun is the knob
const SX1 = WX + TW - TH / 2;       // right end: where the moon waits and totality locks in
const MX_OFF = SX1;                 // moon rest x
const D1 = 50, D2 = 8;              // moon–sun offset at the start / end of the partial-eclipse act

const smooth = (a, b, x) => { const t = clamp((x - a) / (b - a)); return t * t * (3 - 2 * t); };
// Area of intersection of two circles.
function overlap(r1, r2, d) {
  if (d >= r1 + r2) return 0;
  if (d <= Math.abs(r1 - r2)) return Math.PI * Math.min(r1, r2) ** 2;
  const a = r1 * r1 * Math.acos((d * d + r1 * r1 - r2 * r2) / (2 * d * r1));
  const b = r2 * r2 * Math.acos((d * d + r2 * r2 - r1 * r1) / (2 * d * r2));
  const c = 0.5 * Math.sqrt((-d + r1 + r2) * (d + r1 - r2) * (d - r1 + r2) * (d + r1 + r2));
  return a + b - c;
}
// Deterministic hash noise.
const h1 = (n) => { const x = Math.sin(n * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };
const mixC = (a, b, t) => a.map((v, i) => Math.round(lerp(v, b[i], t)));
const rgb = (c, a = 1) => `rgba(${c[0]},${c[1]},${c[2]},${a})`;

// Three-act timeline: leave (p 0→.25), middle act (.25→.75, slow and linear), arrive (.75→1).
// Hermite joins keep the speed continuous; inv() lets a reversal resume from the current spot.
function profile(d1, dm, d3, endSlope = 0) {
  const T = d1 + dm + d3, vm = 0.5 / dm;
  const herm = (u, p0, p1, m0, m1) => {
    const u2 = u * u, u3 = u2 * u;
    return (2 * u3 - 3 * u2 + 1) * p0 + (u3 - 2 * u2 + u) * m0 + (-2 * u3 + 3 * u2) * p1 + (u3 - u2) * m1;
  };
  const at = (tau) => {
    tau = clamp(tau, 0, T);
    if (tau < d1) return herm(tau / d1, 0, 0.25, 0, vm * d1);
    if (tau < d1 + dm) return 0.25 + (tau - d1) * vm;
    return herm((tau - d1 - dm) / d3, 0.75, 1, vm * d3, endSlope * 0.25);
  };
  const inv = (p) => { let a = 0, b = T; for (let i = 0; i < 32; i++) { const m = (a + b) / 2; if (at(m) < p) a = m; else b = m; } return (a + b) / 2; };
  return { T, at, inv };
}
const PON = profile(380, 900, 480);   // ≈1.76 s: sun rolls in, long PARTIAL ECLIPSE, totality at the right
const POFF = profile(380, 860, 460);  // ≈1.70 s: totality breaks, crescent on the other side, sun rolls home

export default class Eclipse extends ToggleBase {
  template() {
    return `
      <style>
        :host { background: #050b1f; }
        canvas { position: absolute; display: block; }
        .hit { position: absolute; left: ${WX - BZ}px; top: ${WY - BZ}px; width: ${TW + BZ * 2}px; height: ${TH + BZ * 2}px; border-radius: ${TH / 2 + BZ}px; }
      </style>
      <canvas></canvas>
      <div class="hit" data-hit role="switch" aria-label="Eclipse"></div>`;
  }

  setup() {
    this.cv = this.$('canvas');
    this.q = 0;              // 0 = day (sun left, moon right) … 1 = totality at the right end
    this.tau = 0; this.run = false; this.on = false;
    this.dys = 1;            // which side the moon passes (crescent flips between directions)
    this.stars = Array.from({ length: 260 }, (_, i) => ({
      x: h1(i * 3.1), y: h1(i * 7.7 + 2), r: 0.25 + h1(i * 1.9) ** 3 * 1.1, ph: h1(i * 5.3) * 6.28, sp: 0.6 + h1(i * 9.1) * 2,
    }));
    this.rays = Array.from({ length: 140 }, (_, i) => ({
      a: (i / 140) * Math.PI * 2 + (h1(i * 4.4) - 0.5) * 0.05, len: h1(i * 2.2), w: 0.4 + h1(i * 6.6) * 1.4, ph: h1(i * 8.8) * 6.28,
    }));
  }

  onResize() {
    const r = this.getBoundingClientRect();
    this.hw = r.width / this.scale; this.hh = r.height / this.scale;
    this.ox = (360 - this.hw) / 2; this.oy = (220 - this.hh) / 2;
    Object.assign(this.cv.style, { left: this.ox + 'px', top: this.oy + 'px' });
    this.ctx = this.sizeCanvas(this.cv, this.hw, this.hh);
  }

  render(on, instant) {
    this.on = on;
    const prof = on ? PON : POFF;
    this.$('.hit').setAttribute('aria-checked', String(on));
    if (instant) { this.q = on ? 1 : 0; this.tau = prof.T; this.run = false; this.dys = on ? -1 : 1; return; }
    this.tau = prof.inv(on ? this.q : 1 - this.q);
    this.run = true;
  }

  tick(t, dt) {
    if (!this.ctx) return;
    this._dt = dt;
    if (this.run) {
      const prof = this.on ? PON : POFF;
      this.tau += dt;
      const p = prof.at(this.tau);
      this.q = this.on ? p : 1 - p;
      if (this.tau >= prof.T) { this.run = false; this.q = this.on ? 1 : 0; }
    }
    // Going in, the moon rides high (crescent low-left); coming out it rides low (crescent high).
    this.dys += ((this.on ? -1 : 1) - this.dys) * Math.min(1, dt / 220);
    this.draw(t / 1000);
  }

  // Sun and moon positions from q.
  bodies() {
    const q = this.q, L = (a, b) => clamp((q - a) / (b - a));
    const leave = L(0, 0.25), mid = L(0.25, 0.75), arr = L(0.75, 1);
    const CEN = CX;
    let sx, dx;
    if (q < 0.25) {
      sx = lerp(SX0, CEN - 8, ease.inOutCubic(leave));
      const mxx = lerp(MX_OFF, CEN - 8 + D1, ease.inOutCubic(leave));
      dx = mxx - sx;
    } else if (q < 0.75) {
      sx = lerp(CEN - 8, CEN + 8, mid);
      dx = lerp(D1, D2, mid);
    } else {
      sx = lerp(CEN + 8, SX1, ease.inOutCubic(arr));
      dx = lerp(D2, 0, ease.outCubic(arr));
    }
    const bump = Math.sin(Math.PI * clamp((q - 0.12) / 0.8));
    const dy = this.dys * 12 * bump;
    return { sx, mx: sx + dx, my: CY + dy };
  }

  draw(s) {
    const g = this.ctx, { hw, hh, ox, oy } = this;
    const { sx: SX, mx, my } = this.bodies();
    const d = Math.hypot(mx - SX, my - CY);
    const vis = clamp(1 - overlap(RS, RM, d) / (Math.PI * RS * RS));   // visible fraction of the sun
    const dk = Math.pow(smooth(0.2, 1, 1 - vis), 1.6);          // sky darkness
    const tot = smooth(0.006, 0, vis);                           // totality (corona) 0..1
    const pf = smooth(0.9, 0.4, vis) * (1 - tot);                // partial-eclipse twilight
    const sb = smooth(0.3, 0.06, vis) * smooth(0.0, 0.02, vis);  // shadow bands near the thin crescent
    const ringNow = vis > 0 && vis < 0.06 ? Math.exp(-(((vis - 0.012) / 0.012) ** 2)) : 0; // diamond ring
    // Hold the flash briefly so it reads on screen, fading as totality settles.
    this.ringMem = Math.max(ringNow, (this.ringMem || 0) - (this._dt || 16) / 320);
    const ring = vis < 0.14 ? this.ringMem : 0;

    g.save();
    g.clearRect(0, 0, hw, hh);
    g.translate(-ox, -oy);                // draw in stage coordinates

    // Page: deep space with faint fixed stars.
    const page = g.createRadialGradient(CX, CY, 20, CX, CY, Math.max(hw, hh) * 0.75);
    page.addColorStop(0, '#0b1430'); page.addColorStop(1, '#03060f');
    g.fillStyle = page; g.fillRect(ox, oy, hw, hh);
    for (const st of this.stars) {
      g.fillStyle = `rgba(200,215,255,${0.28 * (0.35 + st.r * 0.6)})`;
      g.beginPath(); g.arc(ox + st.x * hw, oy + st.y * hh, st.r, 0, 6.283); g.fill();
    }
    // Light leaking past the bezel: warm sunlight by day, pearly corona at totality.
    {
      g.save(); g.globalCompositeOperation = 'lighter';
      const lv = Math.pow(vis, 0.6), lc = smooth(0, 1, dk) * 0.4 + tot * 0.6;
      const lg = g.createRadialGradient(SX, CY, 40, SX, CY, 230);
      lg.addColorStop(0, `rgba(${Math.round(lerp(150, 255, lv))},${Math.round(lerp(170, 170, lv))},${Math.round(lerp(255, 90, lv))},${0.16 * lv + 0.14 * lc})`);
      lg.addColorStop(1, 'rgba(0,0,0,0)');
      g.fillStyle = lg; g.fillRect(ox, oy, hw, hh);
      g.restore();
    }
    // Bezel: dark anodised metal, soft drop shadow, top highlight, faint cool rim.
    g.save();
    g.shadowColor = 'rgba(0,0,0,.7)'; g.shadowBlur = 36; g.shadowOffsetY = 18;
    this.pill(g, WX - BZ, WY - BZ, TW + BZ * 2, TH + BZ * 2); g.fillStyle = '#14171f'; g.fill();
    g.restore();
    let bz = g.createLinearGradient(0, WY - BZ, 0, WY + TH + BZ);
    bz.addColorStop(0, '#4a5163'); bz.addColorStop(0.12, '#262b37'); bz.addColorStop(0.5, '#171a22'); bz.addColorStop(0.88, '#1f232d'); bz.addColorStop(1, '#3a4152');
    this.pill(g, WX - BZ, WY - BZ, TW + BZ * 2, TH + BZ * 2); g.fillStyle = bz; g.fill();
    this.pill(g, WX - BZ + 0.75, WY - BZ + 0.75, TW + BZ * 2 - 1.5, TH + BZ * 2 - 1.5);
    g.strokeStyle = `rgba(150,185,255,${0.22 + 0.12 * dk})`; g.lineWidth = 1.2; g.stroke();
    // Brushed sheen.
    bz = g.createLinearGradient(WX - BZ, 0, WX + TW + BZ, 0);
    bz.addColorStop(0, 'rgba(255,255,255,0)'); bz.addColorStop(0.3, 'rgba(255,255,255,.05)'); bz.addColorStop(0.5, 'rgba(255,255,255,0)'); bz.addColorStop(0.75, 'rgba(255,255,255,.04)'); bz.addColorStop(1, 'rgba(255,255,255,0)');
    this.pill(g, WX - BZ, WY - BZ, TW + BZ * 2, TH + BZ * 2); g.fillStyle = bz; g.fill();
    // Sunlight catching the bezel near the sun.
    if (vis > 0.01) {
      g.save(); g.globalCompositeOperation = 'lighter';
      const sg = g.createRadialGradient(SX, CY, RS, SX, CY, RS + 50);
      sg.addColorStop(0, `rgba(255,190,110,${0.22 * Math.pow(vis, 0.6)})`); sg.addColorStop(1, 'rgba(255,160,80,0)');
      this.pill(g, WX - BZ, WY - BZ, TW + BZ * 2, TH + BZ * 2); g.fillStyle = sg; g.fill();
      g.restore();
    }

    // ── Everything below lives inside the window.
    g.save();
    this.pill(g, WX, WY, TW, TH); g.clip();

    // Sky.
    const dayTop = [12, 38, 92], dayBot = [4, 14, 44], nightTop = [3, 4, 12], nightBot = [1, 1, 5];
    const sky = g.createRadialGradient(SX, CY, 10, SX, CY, TW);
    sky.addColorStop(0, rgb(mixC([40, 86, 168], [10, 12, 26], dk)));
    sky.addColorStop(0.45, rgb(mixC(dayTop, nightTop, dk)));
    sky.addColorStop(1, rgb(mixC(dayBot, nightBot, dk)));
    g.fillStyle = sky; g.fillRect(WX, WY, TW, TH);

    // Stars (faint by day, full at totality).
    for (const st of this.stars) {
      const tw = 0.6 + 0.4 * Math.sin(s * st.sp + st.ph);
      const a = (0.12 + 0.88 * dk) * tw * (0.35 + st.r * 0.6);
      g.fillStyle = `rgba(220,230,255,${a})`;
      g.beginPath(); g.arc(WX + st.x * TW, WY + st.y * TH, st.r * 0.9, 0, 6.283); g.fill();
    }

    // Deep partial eclipse: a 360° sunset glows on the horizon under a violet zenith.
    if (pf > 0.01) {
      const tg = g.createLinearGradient(0, WY, 0, WY + TH);
      tg.addColorStop(0, `rgba(78,44,130,${0.38 * pf})`);
      tg.addColorStop(0.5, `rgba(40,28,72,${0.12 * pf})`);
      tg.addColorStop(0.78, `rgba(255,112,70,${0.3 * pf})`);
      tg.addColorStop(1, `rgba(255,176,96,${0.6 * pf})`);
      g.fillStyle = tg; g.fillRect(WX, WY, TW, TH);
    }

    // Shadow bands: faint ripples racing across the ground just before totality.
    if (sb > 0.01) {
      g.save(); g.translate(CX, CY); g.rotate(-0.32);
      const off = (s * 30) % 9;
      for (let k = -30; k <= 30; k++) {
        const x = k * 9 + off, a = sb * (0.5 + 0.5 * Math.sin(k * 1.9 + s * 4));
        g.fillStyle = `rgba(255,236,210,${0.1 * a})`; g.fillRect(x, -160, 3, 320);
        g.fillStyle = `rgba(0,0,12,${0.16 * a})`; g.fillRect(x + 4.5, -160, 3, 320);
      }
      g.restore();
    }

    g.globalCompositeOperation = 'lighter';
    // Sunlight halo — scales with visible fraction.
    const glow = Math.pow(vis, 0.6);
    if (glow > 0.001) {
      const hR = 80 + 170 * glow;
      const halo = g.createRadialGradient(SX, CY, RS * 0.6, SX, CY, hR);
      halo.addColorStop(0, `rgba(255,214,140,${0.75 * glow})`);
      halo.addColorStop(0.3, `rgba(255,150,60,${0.28 * glow})`);
      halo.addColorStop(1, 'rgba(255,120,40,0)');
      g.fillStyle = halo; g.beginPath(); g.arc(SX, CY, hR, 0, 6.283); g.fill();
      // Slow rotating flare spokes.
      g.save(); g.translate(SX, CY); g.rotate(s * 0.08);
      for (let i = 0; i < 18; i++) {
        const a = (i / 18) * 6.283, L = RS + (30 + 40 * h1(i)) * glow * (0.8 + 0.2 * Math.sin(s * 1.3 + i));
        const lg = g.createLinearGradient(0, 0, Math.cos(a) * L, Math.sin(a) * L);
        lg.addColorStop(0, `rgba(255,220,160,${0.22 * glow})`); lg.addColorStop(1, 'rgba(255,180,90,0)');
        g.strokeStyle = lg; g.lineWidth = 3 + 3 * h1(i * 3);
        g.beginPath(); g.moveTo(0, 0); g.lineTo(Math.cos(a) * L, Math.sin(a) * L); g.stroke();
      }
      g.restore();
    }

    // Corona — soft pearly glow + long streamers, grows into totality.
    const cor = smooth(0.0, 1, dk) * 0.35 + tot * 0.65;
    if (cor > 0.01) {
      const cg = g.createRadialGradient(SX, CY, RS, SX, CY, RS * 1.45);
      cg.addColorStop(0, `rgba(240,245,255,${0.85 * cor})`);
      cg.addColorStop(0.35, `rgba(200,218,255,${0.35 * cor})`);
      cg.addColorStop(1, 'rgba(160,180,255,0)');
      g.fillStyle = cg; g.beginPath(); g.arc(SX, CY, RS * 1.45, 0, 6.283); g.fill();
      // Pearly light filling the whole window evenly (so no side looks cut off).
      g.fillStyle = `rgba(170,190,255,${0.07 * cor})`; g.fillRect(WX, WY, TW, TH);
      g.save(); g.translate(SX, CY); g.rotate(s * 0.03);
      for (const r of this.rays) {
        // Streamers bunch toward the "equator" like a real solar-minimum corona.
        const eq = 0.45 + 0.55 * Math.abs(Math.cos(r.a));
        const L = RS * (1.08 + (0.1 + 0.32 * r.len * r.len) * eq * (0.85 + 0.15 * Math.sin(s * 0.9 + r.ph))) * (0.75 + 0.25 * cor);
        const x1 = Math.cos(r.a) * RS * 0.96, y1 = Math.sin(r.a) * RS * 0.96;
        const x2 = Math.cos(r.a + 0.04 * Math.sin(r.ph)) * L, y2 = Math.sin(r.a + 0.04 * Math.sin(r.ph)) * L;
        const lg = g.createLinearGradient(x1, y1, x2, y2);
        lg.addColorStop(0, `rgba(240,245,255,${0.33 * cor})`); lg.addColorStop(1, 'rgba(200,215,255,0)');
        g.strokeStyle = lg; g.lineWidth = r.w * 1.4;
        g.beginPath(); g.moveTo(x1, y1); g.lineTo(x2, y2); g.stroke();
      }
      g.restore();
    }
    g.globalCompositeOperation = 'source-over';

    // Sun disc with limb darkening and slow granulation.
    const sd = g.createRadialGradient(SX - 4 * K, CY - 5 * K, 2 * K, SX, CY, RS);
    sd.addColorStop(0, '#fffdf2'); sd.addColorStop(0.55, '#ffe9a8'); sd.addColorStop(0.85, '#ffb04a'); sd.addColorStop(1, '#ff7a1c');
    g.fillStyle = sd; g.beginPath(); g.arc(SX, CY, RS, 0, 6.283); g.fill();
    g.save(); g.beginPath(); g.arc(SX, CY, RS, 0, 6.283); g.clip();
    g.globalCompositeOperation = 'soft-light';
    for (let i = 0; i < 24; i++) {
      const a = h1(i * 2.7) * 6.283 + s * 0.05 * (i % 2 ? 1 : -1), rr = Math.sqrt(h1(i * 5.1)) * RS * 0.9;
      g.fillStyle = `rgba(${i % 3 ? 255 : 160},${i % 3 ? 240 : 90},${i % 3 ? 200 : 30},0.35)`;
      g.beginPath(); g.arc(SX + Math.cos(a) * rr, CY + Math.sin(a) * rr, (3 + 4 * h1(i * 9.3)) * K, 0, 6.283); g.fill();
    }
    g.restore();

    // Prominences — tiny pink arcs at the limb, only visible near totality.
    if (tot > 0.01) {
      g.save(); g.globalCompositeOperation = 'lighter';
      for (const [a, sz] of [[-2.3, 1], [0.6, 0.7], [2.6, 0.55]]) {
        const px = SX + Math.cos(a) * RM, py = CY + Math.sin(a) * RM;
        const pg = g.createRadialGradient(px, py, 0, px, py, 5 * sz * K);
        pg.addColorStop(0, `rgba(255,90,120,${0.9 * tot})`); pg.addColorStop(1, 'rgba(255,60,100,0)');
        g.fillStyle = pg; g.beginPath(); g.arc(px, py, 5 * sz * K, 0, 6.283); g.fill();
      }
      g.restore();
    }

    // Moon — grey with an earthshine rim at rest, pure black against the sun.
    const lit = 1 - smooth(0.0, 0.5, 1 - vis);
    const md = g.createRadialGradient(mx - 9 * K, my - 10 * K, 2 * K, mx, my, RM);
    md.addColorStop(0, rgb(mixC([4, 5, 9], [86, 92, 112], lit)));
    md.addColorStop(0.7, rgb(mixC([2, 2, 5], [44, 48, 64], lit)));
    md.addColorStop(1, rgb(mixC([0, 0, 2], [22, 24, 36], lit)));
    g.fillStyle = md; g.beginPath(); g.arc(mx, my, RM, 0, 6.283); g.fill();
    if (lit > 0.02) {
      // Craters.
      g.save(); g.beginPath(); g.arc(mx, my, RM, 0, 6.283); g.clip();
      for (const [cx, cy, cr] of [[-10, -8, 6], [8, 6, 8], [12, -12, 3.5], [-6, 13, 4], [-16, 4, 3]]) {
        g.fillStyle = `rgba(10,12,22,${0.35 * lit})`; g.beginPath(); g.arc(mx + cx * K, my + cy * K, cr * K, 0, 6.283); g.fill();
        g.strokeStyle = `rgba(150,160,190,${0.18 * lit})`; g.lineWidth = 1; g.beginPath(); g.arc(mx + (cx - 0.6) * K, my + (cy - 0.6) * K, cr * K, 3.6, 5.6); g.stroke();
      }
      g.restore();
      g.strokeStyle = `rgba(170,190,255,${0.35 * lit})`; g.lineWidth = 1.4;
      g.beginPath(); g.arc(mx, my, RM - 0.5, 2.6, 5.4); g.stroke();
    }

    // Diamond ring + Baily's beads at the last sliver (left limb, opposite the moon's approach).
    if (vis < 0.14 && (vis > 0 || ring > 0.01)) {
      g.save(); g.globalCompositeOperation = 'lighter';
      const ang = Math.atan2(CY - my, SX - mx);   // last sliver: the limb facing away from the moon
      const bx = SX + Math.cos(ang) * RS, by = CY + Math.sin(ang) * RS;
      const beads = smooth(0.14, 0.02, vis) * smooth(0, 0.004, vis);
      for (let i = -3; i <= 3; i++) {
        if (i === 0) continue;
        const a = ang + i * 0.16 * (1 + vis * 6), fl = 0.6 + 0.4 * Math.sin(this.q * 400 + i * 2.1);
        const px = SX + Math.cos(a) * (RS + 0.3), py = CY + Math.sin(a) * (RS + 0.3);
        const bg = g.createRadialGradient(px, py, 0, px, py, 4.6);
        bg.addColorStop(0, `rgba(255,255,255,${beads * fl * (1 - Math.abs(i) * 0.18)})`); bg.addColorStop(1, 'rgba(255,240,220,0)');
        g.fillStyle = bg; g.beginPath(); g.arc(px, py, 4.6, 0, 6.283); g.fill();
      }
      if (ring > 0.01) {
        const R = 8 + 46 * ring;
        const dg = g.createRadialGradient(bx, by, 0, bx, by, R);
        dg.addColorStop(0, `rgba(255,255,255,${ring})`); dg.addColorStop(0.2, `rgba(255,250,235,${0.7 * ring})`); dg.addColorStop(1, 'rgba(255,230,200,0)');
        g.fillStyle = dg; g.beginPath(); g.arc(bx, by, R, 0, 6.283); g.fill();
        // Cross spikes.
        for (const [dx, dy, L] of [[1, 0, 110], [0, 1, 64], [0.7, 0.7, 34], [0.7, -0.7, 34]]) {
          for (const sgn of [1, -1]) {
            const lg = g.createLinearGradient(bx, by, bx + dx * L * sgn * ring, by + dy * L * sgn * ring);
            lg.addColorStop(0, `rgba(255,255,255,${0.9 * ring})`); lg.addColorStop(1, 'rgba(255,255,255,0)');
            g.strokeStyle = lg; g.lineWidth = 1.3;
            g.beginPath(); g.moveTo(bx, by); g.lineTo(bx + dx * L * sgn * ring, by + dy * L * sgn * ring); g.stroke();
          }
        }
        // Whole-scene flash.
        g.fillStyle = `rgba(255,250,240,${0.12 * ring * ring})`; g.fillRect(WX, WY, TW, TH);
      }
      g.restore();
    }

    // Snow Globe lip: recessed inner shadow + faint lower highlight.
    let lp = g.createLinearGradient(0, WY, 0, WY + 16);
    lp.addColorStop(0, 'rgba(0,0,0,.5)'); lp.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = lp; g.fillRect(WX, WY, TW, 16);
    g.restore();                          // end window clip
    // Corona light spilling over the bezel all round, so the halo reads whole at the pill's end.
    if (tot > 0.01) {
      g.save(); g.globalCompositeOperation = 'lighter';
      const OR = RS + 66, og = g.createRadialGradient(SX, CY, 0, SX, CY, OR);
      og.addColorStop(0, 'rgba(160,180,255,0)'); og.addColorStop((RS + 2) / OR, 'rgba(160,180,255,0)');
      og.addColorStop((RS + 10) / OR, `rgba(215,228,255,${0.3 * tot})`); og.addColorStop(1, 'rgba(160,180,255,0)');
      g.fillStyle = og; g.fillRect(SX - 130, CY - 130, 260, 260);
      g.restore();
    }
    this.pill(g, WX + 0.75, WY + 0.75, TW - 1.5, TH - 1.5); g.strokeStyle = 'rgba(0,0,0,.45)'; g.lineWidth = 1.5; g.stroke();
    this.pill(g, WX + 1.5, WY + 1.5, TW - 3, TH - 3);
    lp = g.createLinearGradient(0, WY, 0, WY + TH);
    lp.addColorStop(0, 'rgba(255,255,255,0)'); lp.addColorStop(0.85, 'rgba(255,255,255,0)'); lp.addColorStop(1, 'rgba(200,220,255,.18)');
    g.strokeStyle = lp; g.lineWidth = 1.2; g.stroke();
    g.restore();
  }

  pill(g, x, y, w, h) {
    const r = h / 2;
    g.beginPath();
    g.moveTo(x + r, y); g.lineTo(x + w - r, y); g.arc(x + w - r, y + r, r, -Math.PI / 2, Math.PI / 2);
    g.lineTo(x + r, y + h); g.arc(x + r, y + r, r, Math.PI / 2, Math.PI * 1.5); g.closePath();
  }
}

customElements.define('tg-eclipse', Eclipse);
